#!/usr/bin/env node
/**
 * Generate the main-process @drone/plugin-api shim from the renderer manifest.
 *
 * The generated file is committed so packaged builds do not depend on a
 * runtime TypeScript loader. `--check` is used by CI to make drift visible.
 */
import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import process from "node:process";

const root = new URL("../", import.meta.url);
const manifestPath = new URL("./src/renderer/src/plugins/host-api.manifest.ts", root);
const outputPath = new URL("./src/main/ui-plugins/plugin-api-shim.generated.ts", root);

const manifestSource = await readFile(manifestPath, "utf8");
const projectionPaths = [
	new URL("./src/renderer/src/plugins/host-api.ts", root),
	new URL("./src/renderer/src/plugins/env.d.ts", root),
	new URL("./resources/ui-plugins/drone-ui.d.ts", root),
];
const projectionSources = await Promise.all(projectionPaths.map((path) => readFile(path, "utf8")));

function readNames(namespace) {
	const match = new RegExp(`${namespace}:\\s*\\[([\\s\\S]*?)\\]`).exec(manifestSource);
	if (!match) throw new Error(`Plugin host API manifest is missing ${namespace}`);
	return [...match[1].matchAll(/"([^"]+)"/g)].map((item) => item[1]);
}

function projectionNames(source, namespace, declaration) {
	const open = declaration === "drone" ? `export const ${namespace}:\\s*\\{` : `${namespace}:\\s*\\{`;
	// Namespace blocks are deliberately shallow in all three projections. The
	// first expression handles multiline blocks; the fallback covers the
	// renderer's compact `i18n: { registerMessages: ... }` object.
	const block =
		new RegExp(`${open}([\\s\\S]*?)\\n\\s*\\}\\s*[,;]?`).exec(source) ??
		new RegExp(`${open}([^}]*)\\}`).exec(source);
	if (!block) throw new Error(`Plugin host API projection is missing ${namespace} (${declaration})`);
	const firstProperty = /^([ \t]*)\S/m.exec(block[1]);
	const indent = firstProperty?.[1] ?? "";
	const escapedIndent = indent.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
	const property = new RegExp(`^${escapedIndent}([A-Za-z_$][\\w$]*)\\s*(?::|\\(|,)`, "gm");
	return [...block[1].matchAll(property)].map((item) => item[1]);
}

const names = {
	components: readNames("components"),
	helpers: readNames("helpers"),
	hooks: readNames("hooks"),
	stores: readNames("stores"),
	i18n: readNames("i18n"),
};

// These projections contain the executable host object, renderer declaration,
// and CLI/plugin declaration. Keep the manifest genuinely single-source by
// failing when a declared public name is missing, or an undeclared name is
// added, in any projection.
const projectionMissing = [];
const projectionKinds = ["host", "env", "drone"];
for (const [namespace, namespaceNames] of Object.entries(names)) {
	const expected = new Set(namespaceNames);
	for (const [index, source] of projectionSources.entries()) {
		const actual = new Set(projectionNames(source, namespace, projectionKinds[index]));
		for (const name of namespaceNames) {
			if (!actual.has(name))
				projectionMissing.push(`${namespace}.${name} missing in ${projectionPaths[index].pathname}`);
		}
		for (const name of actual) {
			if (!expected.has(name))
				projectionMissing.push(`${namespace}.${name} is undeclared in ${projectionPaths[index].pathname}`);
		}
	}
}
if (projectionMissing.length > 0) {
	throw new Error(`Plugin host API manifest drift:\\n${projectionMissing.join("\\n")}`);
}

const shim = [
	"const A = window.DroneUI;",
	"export default A;",
	"export const { version, components, helpers, hooks, stores, i18n } = A;",
	`export const { ${names.components.join(", ")} } = A.components;`,
	`export const { ${names.helpers.join(", ")} } = A.helpers;`,
	`export const { ${names.hooks.join(", ")} } = A.hooks;`,
	`export const { ${names.stores.join(", ")} } = A.stores;`,
	`export const { ${names.i18n.join(", ")} } = A.i18n;`,
].join("\n");

const output = `/** Generated by packages/desktop/scripts/gen-plugin-api.mjs. Do not edit by hand. */\nexport const PLUGIN_API_SHIM =\n\t${JSON.stringify(`${shim}\n`)};\n`;
const check = process.argv.includes("--check");
if (check) {
	const current = await readFile(outputPath, "utf8").catch(() => "");
	if (current !== output) {
		console.error(
			`Generated plugin API shim is stale: ${join("packages/desktop", "src/main/ui-plugins/plugin-api-shim.generated.ts")}`,
		);
		process.exit(1);
	}
	console.log("plugin host API shim is up to date");
} else {
	await writeFile(outputPath, output, "utf8");
	console.log("generated plugin host API shim");
}
